        }

        private string Check(bool value)=>value?"[OK]":"[ ]";private void OnLogAdded(string _)=>RefreshLog();private void RefreshLog(){if(logText==null||AscendanceGameManager.Instance==null)return;logText.text=string.Join("\n",AscendanceGameManager.Instance.Log.TakeLast(7));}

        private GameObject MakePanel(string name,Vector2 min,Vector2 max){var go=new GameObject(name);go.transform.SetParent(canvas.transform,false);var rt=go.AddComponent<RectTransform>();rt.anchorMin=min;rt.anchorMax=max;rt.offsetMin=rt.offsetMax=Vector2.zero;var image=go.AddComponent<Image>();image.color=name=="Hand"||name=="Controls"?panel2:panel;var outline=go.AddComponent<Outline>();outline.effectColor=new Color(gold.r,gold.g,gold.b,0.8f);outline.effectDistance=new Vector2(1.2f,-1.2f);go.AddComponent<RectMask2D>();return go;}
        private Text MakeText(Transform parent,string value,int size,TextAnchor alignment,Color color,Vector2 min,Vector2 max,bool bestFit=false,int minSize=10){var go=new GameObject("Text");go.transform.SetParent(parent,false);var rt=go.AddComponent<RectTransform>();rt.anchorMin=min;rt.anchorMax=max;rt.offsetMin=rt.offsetMax=Vector2.zero;var text=go.AddComponent<Text>();text.raycastTarget=false;text.font=font;text.text=value;text.fontSize=size;text.alignment=alignment;text.color=color;text.horizontalOverflow=HorizontalWrapMode.Wrap;text.verticalOverflow=VerticalWrapMode.Truncate;text.lineSpacing=0.95f;if(bestFit)SetBestFit(text,minSize,size);return text;}
        private static void SetBestFit(Text text,int min,int max){text.resizeTextForBestFit=true;text.resizeTextMinSize=min;text.resizeTextMaxSize=max;}
        private Button MakeButton(Transform parent,string name,string label,Vector2 min,Vector2 max,UnityEngine.Events.UnityAction action){var go=new GameObject(name);go.transform.SetParent(parent,false);var rt=go.AddComponent<RectTransform>();rt.anchorMin=min;rt.anchorMax=max;rt.offsetMin=rt.offsetMax=Vector2.zero;var image=go.AddComponent<Image>();image.color=new Color(0.055f,0.065f,0.075f,0.97f);var outline=go.AddComponent<Outline>();outline.effectColor=new Color(gold.r,gold.g,gold.b,0.8f);var button=go.AddComponent<Button>();button.targetGraphic=image;button.onClick.AddListener(action);var colors=button.colors;colors.highlightedColor=new Color(0.20f,0.18f,0.12f,1f);colors.pressedColor=new Color(0.30f,0.22f,0.08f,1f);colors.disabledColor=new Color(0.055f,0.055f,0.055f,0.55f);button.colors=colors;MakeText(go.transform,label,14,TextAnchor.MiddleCenter,parchment,new Vector2(0.04f,0.04f),new Vector2(0.96f,0.96f),true,8);return button;}
    }

    public sealed class CardHoverRelay:MonoBehaviour,IPointerEnterHandler,IPointerExitHandler{public AscendanceHUD Hud;public string Tooltip;public void OnPointerEnter(PointerEventData e)=>Hud?.ShowCardTooltip(Tooltip);public void OnPointerExit(PointerEventData e)=>Hud?.HideCardTooltip();}
}
